using Shop.Core.Orders;

namespace Shop.Core.Payments;

public interface IPaymentProcessor
{
    string Name { get; }

    PaymentResult Charge(Order order, decimal amount);
}

using Shop.Core.Orders;

namespace Shop.Core.Payments;

public sealed class CardPaymentProcessor : IPaymentProcessor
{
    public string Name => "card";

    public PaymentResult Charge(Order order, decimal amount)
    {
        return new PaymentResult(amount > 0, $"card-{order.Id:N}");
    }
}

using Shop.Core.Orders;

namespace Shop.Core.Payments;

public sealed class PayPalPaymentProcessor : IPaymentProcessor
{
    public string Name => "paypal";

    public PaymentResult Charge(Order order, decimal amount)
    {
        return new PaymentResult(amount > 0 && amount < 10_000m, $"pp-{order.Id:N}");
    }
}

using Shop.Core.Orders;

namespace Shop.Core.Payments;

public abstract class BankPaymentProcessorBase : IPaymentProcessor
{
    public abstract string Name { get; }

    protected abstract string Scheme { get; }

    public PaymentResult Charge(Order order, decimal amount)
    {
        return new PaymentResult(amount > 0, $"{Scheme}-{order.Id:N}");
    }
}

